INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('Mission Software Engineer, Vehicle Software, Computer Vision with Security Clearance','Anduril Industries','United States','Costa Mesa','221000.0','221000.0','USD','Unspecified','Mid-level','Computer Vision','21-02-2026','Adzuna','Anduril Industries is a defense technology company with a mission to transform U.S. and allied military capabilities with advanced technology. By bringing the expertise, technology, and business model of the 21st century''s most innovative companies to the defense industry, Anduril is changing how military systems are designed, built and sold. Anduril''s family of systems is powered by Lattice OS, an AI-powered operating system that turns thousands of data streams into a realtime, 3D command and â€¦');
INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('Senior Open-Source Machine Learning Engineer, Computer Vision - US Remote','Hugging Face','United States','New York City','144000.0','144000.0','USD','Remote','Senior','Computer Vision, Transformers','10-02-2026','Adzuna','At Hugging Face, we''re on a journey to democratize good AI. We are building the fastest growing platform for AI builders with over 11 million users who collectively shared over 2M models, 700k datasets & 600k apps. Our open-source libraries have more than 600k stars on Github. About the Role As an Open-Source ML engineer in Computer Vision , you will work mainly with existing open-source libraries, such as Transformers and Datasets to boost the support for vision or multi-modal models and datasâ€¦');
INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('Machine Learning Engineer III â€“ Computer Vision & Data Systems','Zone 5 Technologies','United States','US','150000.0','175000.0','USD','Unspecified','Mid-level','Computer Vision','27-08-2025','Adzuna','At Zone 5 Technologies, we''re redefining what''s possible in unmanned aircraft systems. Our team of engineers and innovators is developing cutting-edge autonomous solutions that push the boundaries of UAS technology - solving complex challenges that matter. We''re building the future of UAS capabilities, and we''re looking for exceptional talent to join us. If you''re driven by hard problems, energized by rapid innovation, and ready to make an impact on next-generation flight systems, you belong heâ€¦');
