INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('AI Research Engineer','Weekday AI','United States','US','225000.0','225000.0','USD','Unspecified','Mid-level',NULL,'22-08-2025','Adzuna','This role is for one of the Weekday''s clients Min Experience: 6 years JobType: full-time As an AI Research Engineer, you will be responsible for designing, developing, and deploying advanced AI/ML models, contributing to fundamental research, and translating theoretical breakthroughs into practical, scalable systems. You will collaborate with cross-functional teams of data scientists, engineers, and product managers to drive innovation and shape the future of our AI-driven products and servicesâ€¦');
INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('Generalist - Ai Research','YO HR Consultancy','United States','US','73000.0','94000.0','USD','Unspecified','Mid-level','Fine-tuning','21-02-2026','Adzuna','Role Overview Seeking generalist experts to support a large-scale project with a leading AI research partner. The goal is to create and refine a diverse dataset of human-aligned tasks for supervised fine-tuning (SFT) of frontier models. Generalists will contribute by generating realistic prompts, evaluating AI outputs, and iterating on responses to ensure quality and domain relevance. This is a short-term, project-based opportunity ideal for professionals with broad analytical capabilities and â€¦');
INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('AI Research Engineer','Code Metal','United States','Palo Alto','122000.0','122000.0','USD','Unspecified','Mid-level',NULL,'12-11-2025','Adzuna','Our mission is to enable hardware deployment at the speed of software development. We are working towards automatic code transpilation and optimization for any hardware application. In this role, you will collaborate with a small team of talented researchers on ambitious, greenfield projects in generative AI and reinforcement learning. Core responsibilities: Design, execute, and analyze experiments with a high degree of independence Contribute to core models and frameworks Create high-quality dâ€¦');
INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('Physician AI Researcher','Ambience Healthcare','United States','San Francisco','205000.0','300000.0','USD','Unspecified','Mid-level',NULL,'27-04-2025','Adzuna','About Us: Here at Ambience, we never set out to be just another scribe. Weâ€™re building the AI intelligence platform that restores humanity to healthcare and drives meaningful ROI for health systems across the country. Our technology helps providers focus on delivering great care by removing the administrative burden that pulls them away from patients and away from their most impactful work. Ambience delivers real-time coding-aware documentation and clinical workflow support across ambulatory, eâ€¦');
INSERT INTO ai_jobs (job_title,company,country,city,salary_min,salary_max,currency,remote_type,experience_level,required_skills,posted_date,source,job_description) VALUES ('Staff Full Spectrum Cyber AI Researcher with Security Clearance','Leidos','United States','Herndon','157000.0','157000.0','USD','Unspecified','Lead','R','21-02-2026','Adzuna','R-00175446 Description â€‹The Leidos Cyber Accelerator is seeking a hands-on applied researcher to invent, prototype, and operationalize agentic AI systems, and the automation required to deploy them in enterprise environments. You will evaluate emerging agentic patterns (multi-agent coordination, tool use, human-in-the-loop oversight), implement them as working systems, and build reusable automation and integration patterns (e.g., LLM-driven tool connectors/protocols) that enable secure, observaâ€¦');
