USE ai_jobs;

-- ========================== Loading DATAS ========================== 



-- ========================== View The Table ========================== 

SELECT*FROM ai_jobs;

DESCRIBE ai_jobs;

-- ========================== 1. Top 10 Highest Paying AI Jobs ==========================

SELECT job_title,
       MAX(salary_max) AS highest_salary
FROM ai_jobs
GROUP BY job_title
ORDER BY highest_salary DESC
LIMIT 10;


-- ========================== 2. Top 10 Lowest Paying AI Jobs ========================== 

SELECT job_title,
       MIN(salary_min) AS Lowest_salary
FROM ai_jobs
GROUP BY job_title
ORDER BY Lowest_salary DESC
LIMIT 10;


-- ========================== 3. Top 10 Hiring Companies ==========================

SELECT company,
       COUNT(*) AS total_jobs
FROM ai_jobs
GROUP BY company
ORDER BY total_jobs DESC
LIMIT 10;

-- ========================== 4. AI Jobs by Country ==========================

SELECT country,
       COUNT(*) AS total_jobs
FROM ai_jobs
GROUP BY country
ORDER BY total_jobs DESC;

-- ========================== 5. Remote vs Onsite Jobs ==========================

SELECT remote_type,
       COUNT(*) AS total_jobs
FROM ai_jobs
GROUP BY remote_type;

-- ========================== 6. Average Salary by Experience Level ==========================

SELECT experience_level,
       ROUND(AVG(salary_max),2) AS average_salary
FROM ai_jobs
GROUP BY experience_level
ORDER BY average_salary DESC;

-- ========================== 7. Top 10 Cities with Most AI Jobs ==========================

SELECT city,
       COUNT(*) AS total_jobs
FROM ai_jobs
GROUP BY city
ORDER BY total_jobs DESC
LIMIT 10;

-- ========================== 8. Highest Paying Companies ==========================

SELECT company,
       ROUND(AVG(salary_max),2) AS avg_salary
FROM ai_jobs
GROUP BY company
ORDER BY avg_salary DESC
LIMIT 10;

-- ========================== 9. Number of Jobs for Each Currency ==========================

SELECT currency,
       COUNT(*) AS total_jobs
FROM ai_jobs
GROUP BY currency;


-- ========================== 10. Top Skills Demand Analysis ==========================

SELECT required_skills,
       COUNT(*) AS demand
FROM ai_jobs
GROUP BY required_skills
ORDER BY demand DESC
LIMIT 10;

-- ==========================  11. Highest Paying Remote Jobs ==========================
 
 SELECT job_title,
       company,
       salary_max
FROM ai_jobs
WHERE remote_type = 'Remote'
ORDER BY salary_max DESC
LIMIT 10;

-- ========================== 12. Top 5 Companies Hiring for Senior Roles ==========================

SELECT company,
       COUNT(*) AS total_openings
FROM ai_jobs
WHERE experience_level = 'Senior'
GROUP BY company
ORDER BY total_openings DESC
LIMIT 5;